  'dl.chromeTitle': "Chrome Plugin",
  'dl.chromeAbout': "Chrome Plugin-നെക്കുറിച്ച്",
  'dl.chromeDesc': "OpenAlgo Chrome Plugin ഉപയോഗിച്ച് നിങ്ങളുടെ ബ്രൗസറിൽ നിന്ന് നേരിട്ട് ട്രേഡ് ചെയ്യാം. ചാർട്ടുകൾ അനലൈസ് ചെയ്യുമ്പോഴോ മാർക്കറ്റ് ന്യൂസ് വായിക്കുമ്പോഴോ ക്വിക്ക് ഓർഡർ പ്ലേസ്മെന്റിന് അനുയോജ്യം.",
