  'dl.excelDesc': "OpenAlgo Excel Add-in ഉപയോഗിച്ച് Microsoft Excel-ൽ നിന്ന് നേരിട്ട് ട്രേഡ് ചെയ്യാം. സ്പ്രെഡ്ഷീറ്റ്-അധിഷ്ഠിത ട്രേഡിംഗും അനാലിസിസും ഇഷ്ടപ്പെടുന്ന ട്രേഡർമാർക്ക് അനുയോജ്യം.",
