  'skill.bc1t': "ആദ്യ തവണ സെറ്റപ്പ്",
  'skill.bc1d': "നിങ്ങളുടെ മെഷീനിൽ ബാക്ക്ടെസ്റ്റുകൾ റൺ ചെയ്യാൻ വേണ്ടതെല്ലാം തയ്യാറാക്കുന്നു. ഒരിക്കൽ റൺ ചെയ്യൂ.",
  'skill.bc2t': "ഒരു സ്ട്രാറ്റജി ബാക്ക്ടെസ്റ്റ് ചെയ്യൂ",
  'skill.bc2d': "യാഥാർത്ഥ്യമായ ബ്രോക്കറേജും നികുതികളും സഹിതം ഏത് സ്ട്രാറ്റജിയും പഴയ ഡേറ്റയിൽ റൺ ചെയ്യൂ. ലളിതമായ ഇംഗ്ലീഷിൽ ഒരു പൂർണ്ണ റിപ്പോർട്ടും, കൂടാതെ ഒരു പ്രോ-ഗ്രേഡ് PDF-സ്റ്റൈൽ ടിയർഷീറ്റും ലഭിക്കും.",
