  'skill.be5': "RELIANCE-ൽ 3 സ്ട്രാറ്റജികൾ താരതമ്യം ചെയ്യൂ",
  'skill.be6': "ബിറ്റ്കോയിനിൽ EMA crossover ടെസ്റ്റ് ചെയ്യൂ",
