  'skill.installSub': "നിങ്ങൾക്ക് ചേരുന്ന ലെവൽ തിരഞ്ഞെടുക്കൂ. നിങ്ങളുടെ ടെർമിനലിൽ ഒരു വരി പേസ്റ്റ് ചെയ്യൂ - അത്രമാത്രം.",
