  'skill.docsHelp': "വിശദമായ സെറ്റപ്പ് സഹായം വേണോ?",
  'skill.docsHelpLink': "മുഴുവൻ ഡോക്സ് വായിക്കൂ",
  'skill.ctaTitle': "കനത്ത പണി നിങ്ങളുടെ AI ചെയ്യട്ടെ.",
  'skill.ctaSub': "ഒരിക്കൽ ഇൻസ്റ്റാൾ ചെയ്യൂ. ലളിതമായ ഇംഗ്ലീഷിൽ ചോദിക്കൂ. ഇന്ത്യൻ, US, അല്ലെങ്കിൽ ക്രിപ്റ്റോ മാർക്കറ്റുകളിൽ സെക്കൻഡുകൾക്കുള്ളിൽ ചാർട്ടുകളും സ്കാനറുകളും ബാക്ക്ടെസ്റ്റുകളും നേടൂ.",
