  // WABridge page
  'wab.badgeOpenSource': "ഓപ്പൺ സോഴ്‌സ്",
  'wab.heroTag': "ഒരു ലളിതമായ WhatsApp HTTP ബ്രിഡ്ജ്.",
  'wab.heroDesc': "CLI വഴി നിങ്ങളുടെ WhatsApp ലിങ്ക് ചെയ്യൂ, പിന്നെ ലളിതമായ REST API വഴി സന്ദേശങ്ങൾ അയക്കൂ. ടെക്സ്റ്റ്, ഇമേജുകൾ, വീഡിയോ, ഓഡിയോ, ഡോക്യുമെന്റുകൾ - വ്യക്തികൾ, ഗ്രൂപ്പുകൾ, ചാനലുകൾ എന്നിവയ്ക്ക് പിന്തുണ.",
  'wab.orRun': "അല്ലെങ്കിൽ നേരിട്ട് പ്രവർത്തിപ്പിക്കൂ:",
  'wab.ctaNode': "Node.js CLI",
  'wab.ctaPython': "Python SDK",
  'wab.howTitle': "എങ്ങനെ പ്രവർത്തിക്കുന്നു",
  'wab.howDesc': "WABridge നിങ്ങളുടെ ആപ്ലിക്കേഷനുകൾക്കും WhatsApp-നും ഇടയിൽ നിന്ന്, ഒരു ലോക്കൽ HTTP സെർവർ വഴി സന്ദേശങ്ങൾ റൂട്ട് ചെയ്യുന്നു.",
  'wab.howCaption': "നിങ്ങളുടെ ആപ്പ് WABridge-ലേക്ക് HTTP അഭ്യർത്ഥനകൾ അയക്കുന്നു, അത് അവയെ WhatsApp-ലേക്ക് എത്തിക്കുന്നു.",
  'wab.f1t': "ലളിതമായ REST API",
  'wab.f1d': "ഒരു സന്ദേശം അയക്കാൻ ഒരു POST അഭ്യർത്ഥന. സങ്കീർണ്ണമായ SDK-കളോ auth ഫ്ലോകളോ വേണ്ട.",
  'wab.f2t': "സമ്പന്നമായ മീഡിയ",
  'wab.f2d': "ഇമേജുകൾ, വീഡിയോകൾ, വോയ്സ് നോട്ടുകൾ, ഡോക്യുമെന്റുകൾ എന്നിവ അയക്കൂ. URL-കളും ലോക്കൽ ഫയൽ പാതകളും പിന്തുണയ്ക്കുന്നു.",
  'wab.f3t': "ഗ്രൂപ്പുകളും ചാനലുകളും",
  'wab.f3d': "വ്യക്തികൾ, ഗ്രൂപ്പുകൾ, ചാനലുകൾ എന്നിവയ്ക്ക് അയക്കൂ. അവയുടെ JID-കൾ സഹിതം ഗ്രൂപ്പുകൾ പ്രോഗ്രാമാറ്റിക്കായി ലിസ്റ്റ് ചെയ്യൂ.",
  'wab.f4t': "സ്വയം ഹോസ്റ്റ് ചെയ്തത്",
  'wab.f4d': "നിങ്ങളുടെ മെഷീനിൽ പ്രവർത്തിക്കുന്നു. തേഡ്-പാർട്ടി ക്ലൗഡ് സേവനങ്ങൾ ഇല്ല. നിങ്ങളുടെ സന്ദേശങ്ങൾ ലോക്കൽ ആയി തന്നെ നിലനിൽക്കുന്നു.",
  'wab.f5t': "Python SDK",
  'wab.f5d': "ഒരൊറ്റ ഫംഗ്ഷൻ കോൾ ഉപയോഗിച്ച് Python-ൽ നിന്ന് സന്ദേശങ്ങൾ അയക്കൂ. Sync-ഉം async-ഉം ബിൽറ്റ്-ഇൻ പിന്തുണ.",
  'wab.f6t': "ഇന്ററാക്ടീവ് CLI",
  'wab.f6d': "ടെർമിനലിൽ നിന്ന് സന്ദേശങ്ങൾ ഇന്ററാക്ടീവായി പരീക്ഷിക്കൂ. QR കോഡ് അല്ലെങ്കിൽ പെയറിംഗ് കോഡ് വഴി ലിങ്ക് ചെയ്യൂ.",
  'wab.qsTitle': "ക്വിക്ക് സ്റ്റാർട്ട്",
