  'wab.api1d': "WhatsApp കണക്ഷൻ സ്റ്റാറ്റസ് പരിശോധിക്കൂ",
  'wab.api2d': "എല്ലാ WhatsApp ഗ്രൂപ്പുകളും അവയുടെ JID-കൾ സഹിതം ലിസ്റ്റ് ചെയ്യൂ",
  'wab.api3d': "ടെക്സ്റ്റ്, ഇമേജ്, വീഡിയോ, ഓഡിയോ, അല്ലെങ്കിൽ ഡോക്യുമെന്റ് അയക്കൂ",
