  'sip.hero.h1b': "സെർവർ ഹോസ്റ്റിംഗ്",
  'sip.hero.desc': "SEBI-യുടെ സ്റ്റാറ്റിക് IP കംപ്ലയൻസ്, OpenAlgo നിങ്ങളുടെ സ്വന്തം സെർവറിൽ ഡിപ്ലോയ് ചെയ്യുന്നത്, നിങ്ങളുടെ ട്രേഡിംഗ് ഇൻഫ്രാസ്ട്രക്ചർ സുരക്ഷിതമാക്കുന്നത് എന്നിവയെക്കുറിച്ച് അറിയേണ്ട എല്ലാം.",
