  'sip.hero.tag3': "സുരക്ഷാ മികച്ച രീതികൾ",
  'sip.s1.title': "എന്താണ് സ്റ്റാറ്റിക് IP കംപ്ലയൻസ്?",
  'sip.s1.sub': "എല്ലാ റീട്ടെയിൽ ആൽഗോ ട്രേഡർമാരും ഓർഡറുകൾ ഒരു നിശ്ചിത IP വിലാസത്തിലൂടെ റൂട്ട് ചെയ്യണമെന്ന് SEBI നിഷ്കർഷിക്കുന്നു.",
  'sip.s1.introA': "പ്രാബല്യ തീയതി:",
  'sip.s1.introDate': "2026 ഏപ്രിൽ 1",
  'sip.s1.introB': " മുതൽ, ബ്രോക്കർ API ഉപയോഗിക്കുന്ന എല്ലാ റീട്ടെയിൽ ആൽഗോ ട്രേഡർമാരും തങ്ങളുടെ ഓർഡറുകൾ വൈറ്റ്‌ലിസ്റ്റ് ചെയ്ത ഒരു സ്റ്റാറ്റിക് IP വിലാസത്തിൽ നിന്ന് ഉത്ഭവിക്കുന്നുവെന്ന് ഉറപ്പാക്കണം. സ്വന്തം സ്ട്രാറ്റജികളോ ബോട്ടുകളോ ട്രേഡിംഗ് ഇൻഫ്രാസ്ട്രക്ചറോ കൈകാര്യം ചെയ്യുന്ന ആർക്കും ഇത് ബാധകമാണ്.",
